import { z } from "zod";

export const editNewUserSchema = z
  .object({
    first_name: z.string().min(1, "validation.required"),
    last_name: z.string().min(1, "validation.required"),
    email: z.string().email("validation.email_invalid"),
    phone_number: z.string().optional(),
    role_id: z.union([z.number(), z.string()]).optional(),
    role: z.string().optional(),
    role_name: z.string().optional(),
    role_type: z.string().optional(),
    user_type: z.string().optional(),
    developer_id: z.number().optional(),
    developer_role: z.string().optional(),
    status: z.enum(["active", "inactive", "banned"]).optional(),
    description: z.string().optional(),
    profile_picture: z.string().optional(),
  });

export type EditNewUserInput = z.infer<typeof editNewUserSchema>;